/// Docstring for a dotted path under `builtins`, if CPython 3.13 has one.
pub fn builtin_doc_for(path: &str) -> Option<&'static str> {
    BUILTIN_DOCS
        .binary_search_by(|(k, _)| k.cmp(&path))
        .ok()
        .map(|i| BUILTIN_DOCS[i].1)
}
